return {api_version=1,id="EX1_126",name="Betrayal",text="Force an enemy minion to deal its damage to the minions next to it.",set="EXPERT1",type="spell",class="rogue",rarity="common",cost=2,target_mode="required",targets=function(ctx,self)return ctx:enemy_minions(self)end,on_play=function(ctx,self,target)local a=ctx:entity(target).attack;local hits={};for _,e in ipairs(ctx:adjacent_minions(target))do hits[#hits+1]={e,a}end;cardlib.effects.damage_batch_from(ctx, target,hits)end}
